/**
 * @file    fuente.c
 * @brief   Patrones de puntos de las tres fuentes de mapa de bits de la biblioteca lcd_ (8x16,
 * 12x24 y 16x32 píxeles).
 *
 * @details Son **las mismas fuentes que usaba la biblioteca glcd_** de la plataforma LPC4088:
 * se han extraído, byte a byte, de los objetos fuente_8x16.o, fuente_12x24.o y fuente_16x32.o de
 * la biblioteca base_lpc40xx.lib del curso anterior, y se han vuelto a escribir en C con los
 * símbolos de fuente.h, en los que cada `X` es un píxel encendido y cada `_` uno apagado. Así se
 * puede *ver* cada carácter leyendo este fichero.
 *
 * Cada fuente contiene los 224 caracteres del 32 (espacio) al 255, en la codificación
 * **ISO-8859-1 (Latin-1)**: del 32 al 126 es ASCII, y del 160 al 255 están las letras acentuadas,
 * la ñ, la ç, los signos de apertura ¡ y ¿, el símbolo de grado, etc. Los códigos del 127 al 159
 * no tienen dibujo (se imprimen como un espacio).
 *
 * Cada fila de un carácter ocupa ANCHO/8 bytes redondeado hacia arriba (1 byte en la de 8x16, 2 en
 * la de 12x24 —los 4 bits de menor peso del segundo byte no se usan— y 2 en la de 16x32), con el
 * píxel de más a la izquierda en el bit de mayor peso. Las filas van de arriba abajo.
 *
 * @author      Alejandro Lara Doña - alejandro.lara(at)uca.es | Eduardo Romero
 * @date        2014/2026
 * @version   3.0
 *
 * @copyright GNU General Public License version 3 or later
 */

